CREATE TABLE IF NOT EXISTS trade_order (id BIGINT NOT NULL AUTO_INCREMENT,order_no VARCHAR(40) NOT NULL,member_id BIGINT NOT NULL,total_amount DECIMAL(19,2) NOT NULL,use_point BIGINT NOT NULL DEFAULT 0,give_point BIGINT NOT NULL DEFAULT 0,address_id BIGINT NULL,delivery_type INT NULL,receiver_name VARCHAR(100) NULL,receiver_mobile VARCHAR(32) NULL,receiver_area_id BIGINT NULL,receiver_detail_address VARCHAR(500) NULL,delivery_price DECIMAL(19,2) NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL,comment_status BOOLEAN NULL,finish_time DATETIME NULL,remark VARCHAR(500) NULL,create_by VARCHAR(64) NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_by VARCHAR(64) NULL,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_trade_order_no(order_no),KEY idx_trade_order_member_created(member_id,create_time),KEY idx_trade_order_status_created(status,create_time),CONSTRAINT chk_trade_order_total CHECK(total_amount>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='交易订单';
CREATE TABLE IF NOT EXISTS trade_order_item (id BIGINT NOT NULL AUTO_INCREMENT,order_id BIGINT NOT NULL,comment_status BOOLEAN NULL,sku_id BIGINT NOT NULL,spu_id BIGINT NULL,spu_name VARCHAR(200) NULL,properties LONGTEXT NULL,pic_url VARCHAR(1024) NULL,product_code VARCHAR(64) NOT NULL,product_name VARCHAR(200) NOT NULL,unit_price DECIMAL(19,2) NOT NULL,quantity INT NOT NULL,line_amount DECIMAL(19,2) NOT NULL,pay_amount DECIMAL(19,2) NULL,delivery_price DECIMAL(19,2) NOT NULL DEFAULT 0,create_by VARCHAR(64) NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_by VARCHAR(64) NULL,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_trade_order_item_order(order_id),CONSTRAINT fk_trade_order_item_order FOREIGN KEY(order_id) REFERENCES trade_order(id),CONSTRAINT chk_trade_order_item_quantity CHECK(quantity>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='交易订单明细';